-- Resources content for Sourcework analysis, Phase E: piece formats, Draft with AI and the
-- assistant in a piece (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or script block by block, or draft it from a format, then edit by hand or with the assistant. Every version is kept.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'Added Draft with AI and the assistant',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a wrap, voicer or script you build from your own narration and the project's excerpts. It starts blank. You can write it block by block, or let AI draft a first version from a format and then edit it by hand or with the assistant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type. The Pieces list shows each piece's length and when it last changed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Draft with AI (optional)"}]},{"type":"paragraph","content":[{"type":"text","text":"On an empty piece, choose "},{"type":"text","text":"Draft with AI","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format, such as Radio wrap, which sets the length, how many actualities and the order of sections. Under Material, the project's accepted themes are all ticked; untick any you want left out. Suggested themes are listed but can't be used until someone accepts them. Add a direction if you like, then choose "},{"type":"text","text":"Generate draft","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"It takes a minute or two. The model writes the narration only. Every actuality is one of the project's excerpts, placed by the code, so the words and the audio are always the speaker's own. It works only from accepted themes, their accepted data points and the project's excerpts, and it leaves a bracketed note such as [CHECK: year] where the material doesn't say something it needs."}]},{"type":"paragraph","content":[{"type":"text","text":"You land back in the editor with the draft in place and a note saying which format drafted it and its length. "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on that note puts the piece back as it was. Draft with AI is offered only on an empty piece; to start over later, ask the assistant. A piece with no target length takes the format's."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose Excerpt to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time. Select "},{"type":"text","text":"Set a target","marks":[{"type":"bold"}]},{"type":"text","text":" to give the piece a length such as 1:00 and see how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask the assistant"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the assistant from "},{"type":"text","text":"Assistant","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or start over from a format. Anything you have typed is saved before your message goes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It changes only what you ask, and says what it changed. Its reply lists the tools it used."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It places and swaps excerpts by id. It can't change what a speaker said, and the lengths it reports come from the same arithmetic as the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each block it changed is marked "},{"type":"text","text":"Edited by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Added by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on the mark puts that block back. The marks stay until you next edit the piece yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a + row, Ask the assistant to write it opens the assistant with a request for narration at that spot, for you to finish and send."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every draft."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists the versions with who saved each one, and whether it was you, Draft with AI or the assistant. Restore saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drafting and the assistant send the piece's material (accepted themes, data points and the excerpts' words) to an outside service, as extraction does. Building a piece by hand doesn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Pieces list says how each piece was made: Written by hand, or the format that drafted it, then edited."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-piece-formats',
  p_tool_key => 'transcription',
  p_title => 'Maintaining piece formats',
  p_summary => 'For editors: the length, actualities, sections and style Draft with AI follows. Edit, try a draft on a project, publish and roll back.',
  p_screen_keys => array['sourcework.formats'],
  p_sort_order => 21,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece format is the shape and wording Draft with AI follows: its length, how many actualities it uses, its sections in order and a style paragraph. Editors maintain formats; you need the Editor role on Sourcework, which an administrator grants on the user's access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a format"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Prompts and formats","marks":[{"type":"bold"}]},{"type":"text","text":" from the Projects page and choose "},{"type":"text","text":"Piece formats","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format on the left (on a phone, from the list at the top). Your changes save themselves as a draft only you can see."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Length","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Plus or minus","marks":[{"type":"bold"}]},{"type":"text","text":": how long the piece should run, such as 1:00 within 0:05."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Actualities","marks":[{"type":"bold"}]},{"type":"text","text":": the fewest and most clips the piece should use."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sections, in order","marks":[{"type":"bold"}]},{"type":"text","text":": each is Narration or Actuality with one line of guidance. Use ⋮ to move a section, switch its kind, add one below or remove it; on a desktop you can also drag ⋮⋮. The + under the list adds a section at the end."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Style","marks":[{"type":"bold"}]},{"type":"text","text":": how the narration should read. Write placeholders the reporter fills in, such as [REPORTER NAME], in square brackets."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The model writes only narration; actualities are always the project's own excerpts. A format can't change that, and it can't make the model type out a quote."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" drafts a piece from one project's accepted themes and excerpts with your draft and with the live version, and shows the two side by side with their lengths and how many actualities each used. Add a direction if you want to test one. Nothing is added to the project, and results are kept for 14 days and are visible only to you."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version. Reporters' next drafts follow it; pieces already drafted keep the version they were drafted from."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists every version with its note and how many pieces it made. Edit from this version starts a draft from it, and Make live again moves an earlier version back into use. Nothing is deleted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ New format adds a format. It isn't offered to reporters until you publish it. Rename changes its name everywhere."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The formats to start with"}]},{"type":"paragraph","content":[{"type":"text","text":"Four formats come built in: Radio wrap (1:00, two or three actualities), Voicer (0:45, the reporter's voice only), Script (3:00, three to six actualities) and Cut and copy (0:45, one actuality with host copy and a tag). Change them like any other format."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-15-sourcework-draft-with-ai',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-15',
  p_title => 'Sourcework: draft a piece with AI, and the assistant in a piece',
  p_guide_slugs => array['sourcework-pieces', 'sourcework-piece-formats'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework pieces can now be drafted with AI. On an empty piece, choose Draft with AI, pick a format such as Radio wrap, keep or untick the project's accepted themes, add a direction if you like, and generate: the model writes the narration and places the project's own excerpts, so every quote is the speaker's recording. The assistant now works inside a piece, too. It knows which piece you have open, can tighten narration, add a line, move, swap or trim a clip, or start over from a format, and marks each block it changed with an Undo. Editors maintain the formats under Prompts and formats, and can try a draft of a format on a project before publishing it."}]}]}$body$
);
